// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/auth/magic-links", wrapper.RequestMagicLink)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/auth/magic-link-redemptions", wrapper.RedeemMagicLink)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/auth/registrations", wrapper.Register)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/auth/password-sessions", wrapper.SignInWithPassword)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/auth/password-resets", wrapper.RequestPasswordReset)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/auth/password-reset-redemptions", wrapper.ResetPassword)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/auth/passkey-challenges", wrapper.BeginPasskeySignIn)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/auth/passkey-sessions", wrapper.FinishPasskeySignIn)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/auth/session", wrapper.SignOut)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/auth/sessions", wrapper.SignOutEverywhere)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/me", wrapper.GetMe)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/me/passkey-challenges", wrapper.BeginPasskeyRegistration)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/me/passkeys", wrapper.FinishPasskeyRegistration)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/me/totp", wrapper.BeginTotpEnrollment)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/me/totp/confirmation", wrapper.ConfirmTotpEnrollment)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/me/totp/deactivation", wrapper.DisableTotp)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/tenants", wrapper.ListTenants)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/tenants", wrapper.CreateTenant)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/tenants/{tenant}", wrapper.GetTenant)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/tenants/{tenant}/members", wrapper.ListMembers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/tenants/{tenant}/members", wrapper.AddMember)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/tenants/{tenant}/members/{member}", wrapper.RemoveMember)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/tenants/{tenant}/members/{member}", wrapper.GetMember)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/tenants/{tenant}/members/{member}", wrapper.UpdateMember)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/tenants/{tenant}/tokens", wrapper.ListTokens)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/tenants/{tenant}/tokens", wrapper.CreateToken)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/tenants/{tenant}/tokens/{token}", wrapper.RevokeToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/tenants/{tenant}/tokens/{token}", wrapper.GetToken)

	return m
}

